class FileHandle {
    FILE* handle;
public:
    FileHandle(const char* path) {
        handle = fopen(path, "r");
        if (!handle) throw std::runtime_error("Open failed");
    }
    ~FileHandle() {
        if (handle) fclose(handle); // Dtor releases resource
    }
    FileHandle(const FileHandle&) = delete; // Enforce single ownership
};

void process_data() {
    FileHandle f("data.txt");
    // ... use f ...
} // f goes out of scope, destructor automatically closes file.
